insert into public.root_methods (device_id, name, weight, difficulty, summary, body_md, requires, links, play_integrity_notes, admin_curated, provenance)
select d.id, x.name, x.weight, x.difficulty, x.summary, x.body_md, x.requires, x.links, x.play_integrity_notes, x.admin_curated, x.provenance
from jsonb_to_recordset($seed$[{"device_id": null, "name": "KernelSU Next", "weight": 100, "difficulty": "moderate", "summary": "Kernel-based root with full module support — best default choice and Play Integrity posture in 2026.", "body_md": "Flash a KernelSU Next build for your kernel (or patch boot/init_boot), then manage modules and per-app profiles in the manager.", "requires": ["unlocked bootloader", "GKI-compatible kernel"], "links": [{"label": "KernelSU Next (GitHub)", "url": "https://github.com/KernelSU-Next/KernelSU-Next"}, {"label": "Docs", "url": "https://kernelsu.org"}], "play_integrity_notes": "Strongest out-of-box posture; add Play Integrity Fix module if a bank still complains.", "admin_curated": true, "provenance": "community"}, {"device_id": null, "name": "KernelSU", "weight": 90, "difficulty": "moderate", "summary": "The original kernel-space root. Stable, shares the Magisk module format.", "body_md": "Flash a KernelSU-enabled kernel or patch the boot image; install the manager app.", "requires": ["unlocked bootloader", "GKI 2.0 kernel (Android 12+ launch devices) or custom GKI kernel"], "links": [{"label": "KernelSU", "url": "https://kernelsu.org"}], "play_integrity_notes": "Zygisk + Play Integrity Fix recommended for banking apps.", "admin_curated": true, "provenance": "community"}, {"device_id": null, "name": "Magisk", "weight": 80, "difficulty": "easy", "summary": "The classic systemless root — patches boot images, leaves /system untouched.", "body_md": "Patch the stock boot/init_boot image in the Magisk app, flash it in fastboot, reboot.", "requires": ["unlocked bootloader", "stock boot image for your exact build"], "links": [{"label": "Magisk (GitHub)", "url": "https://github.com/topjohnwu/Magisk"}], "play_integrity_notes": "Add DenyList/Zygisk + Play Integrity Fix on Android 14+.", "admin_curated": true, "provenance": "community"}, {"device_id": null, "name": "APatch", "weight": 60, "difficulty": "advanced", "summary": "Kernel-patching root for kernels where KernelSU doesn't build. Magisk-style UI.", "body_md": "Follow APatch docs for the target kernel; patch and flash per instructions.", "requires": ["unlocked bootloader", "kernel 4.14+ with KPM support"], "links": [{"label": "APatch (GitHub)", "url": "https://github.com/bmax121/APatch"}], "play_integrity_notes": "Similar posture to KernelSU, smaller community.", "admin_curated": true, "provenance": "community"}, {"device_id": null, "name": "Magisk Delta / Kitsune", "weight": 40, "difficulty": "moderate", "summary": "Community Magisk fork with built-in hiding (MagiskHide-era approach).", "body_md": "Install Kitsune Mask, patch the boot image, flash, configure built-in hiding.", "requires": ["unlocked bootloader"], "links": [{"label": "Kitsune Mask (GitLab)", "url": "https://gitlab.com/HuskyDG/magisk-files"}], "play_integrity_notes": "Convenient hiding; upstream + modules is more future-proof.", "admin_curated": true, "provenance": "community"}, {"device_id": null, "name": "SuperSU (legacy)", "weight": 10, "difficulty": "easy", "summary": "Chainfire's original root. For pre-2016 devices only.", "body_md": "Flash the SuperSU zip in custom recovery on legacy devices.", "requires": ["custom recovery"], "links": [{"label": "CF-Auto-Root archive", "url": "https://autoroot.chainfire.eu"}], "play_integrity_notes": "Historic reference only.", "admin_curated": true, "provenance": "community"}]$seed$) as x(device_id text, name text, weight int, difficulty difficulty_level, summary text, body_md text, requires text[], links jsonb, play_integrity_notes text, admin_curated boolean, provenance provenance_kind)
left join public.devices d on d.slug = x.device_id
where (x.device_id::text) is null or d.id is not null;
